package fasttouch.demos;

import fasttouch.FastTouch;

public class ConsoleDemo {
    public static void main(String[] args) throws Exception {
        // 1. Force the console window title using ANSI escape codes
        String windowTitle = "FastTouch Console Demo " + System.currentTimeMillis();
        System.out.print("\033]0;" + windowTitle + "\007");

        // Wait a moment for Windows to process the title change
        Thread.sleep(200);

        System.out.println("==========================================");
        System.out.println("FastTouch Console Demo");
        System.out.println("==========================================\n");
        System.out.println("Attempting to hook into Console Window...");

        // 2. Initialize FastTouch by finding the console window
        FastTouch touch = FastTouch.create(windowTitle);

        System.out.println("\nSUCCESS! Touch Engine attached to terminal!");
        System.out.println("Please touch the console window...");

        // 3. Register a Touch Listener
        touch.addListener(point -> {
            // We use ANSI to move the cursor down below the header and print the event
            // Note: Since multi-touch fires very fast, we just print the stream
            if (point.state == FastTouch.State.DOWN) {
                System.out.printf("[DOWN] ID: %d | Pos: %d,%d | Pressure: %d | Size: %dx%d\n", 
                    point.id, point.x, point.y, point.pressure, point.width, point.height);
            } else if (point.state == FastTouch.State.UP) {
                System.out.printf("  [UP] ID: %d\n", point.id);
            }
        });

        // 4. Start polling and keep the thread alive
        touch.start();

        while (true) {
            Thread.sleep(100);
        }
    }
}

package fasttouch.benchmark;

import org.openjdk.jmh.results.RunResult;
import org.openjdk.jmh.runner.Runner;
import org.openjdk.jmh.runner.options.Options;
import org.openjdk.jmh.runner.options.OptionsBuilder;

import java.util.Collection;

public class BenchmarkRunner {

    public static void main(String[] args) throws Exception {
        System.out.println("===========================================");
        System.out.println("FastTouch Benchmark (v0.1.0)");
        System.out.println("===========================================\n");

        System.out.println("--------------------------------------------");
        System.out.println("|  FastTouch Math & JNI Overhead Test      |");
        System.out.println("--------------------------------------------");

        System.out.println("\n[INFO] Initializing JMH Runner...");
        System.out.println("This will take a few minutes to complete as JMH isolates,");
        System.out.println("warms up, and measures throughput rigorously.\n");

        Options opt = new OptionsBuilder()
                .include(TouchBenchmark.class.getSimpleName())
                .jvmArgs("--sun-misc-unsafe-memory-access=allow")
                .forks(1)
                // Optionally add GC profiler to prove zero allocation
                // .addProfiler("gc")
                .build();

        Collection<RunResult> results = new Runner(opt).run();

        System.out.println("\n===========================================");
        System.out.println("FastTouch Benchmark Results Summary:");
        System.out.println("===========================================\n");

        System.out.printf("%-30s | %-15s | %-10s%n", "Benchmark", "Score (ops/ms)", "Error");
        System.out.println("------------------------------------------------------------------");

        for (RunResult result : results) {
            String name = result.getPrimaryResult().getLabel();
            double score = result.getPrimaryResult().getScore();
            double error = result.getPrimaryResult().getScoreError();

            System.out.printf("%-30s | %10.3f      |  %7.3f%n", name, score, error);
        }

        System.out.println("------------------------------------------------------------------");
        System.out.println("\n[DONE] Benchmark Complete.");
    }
}

package fasttouch.benchmark;

import fasttouch.FastGesture;
import fasttouch.FastTouch;
import fasttouch.FastTouch.TouchPoint;
import org.openjdk.jmh.annotations.*;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
@State(Scope.Thread)
public class TouchBenchmark {

    private FastGesture fastGesture;
    private Map<Integer, TouchPoint> touches;

    @Setup(Level.Iteration)
    public void setup() {
        fastGesture = new FastGesture(new FastGesture.GestureListener() {
            @Override public void onPan(float dx, float dy, float x, float y) {}
            @Override public void onPinchStart(float centerX, float centerY) {}
            @Override public void onPinchUpdate(float scale, float angleDelta, float distance, float centerX, float centerY) {}
            @Override public void onPinchEnd() {}
        }, point -> true);

        touches = new HashMap<>();
        // Simulate two fingers moving
        touches.put(0, new TouchPoint(0, 100, 100, 128, 10, 10, System.currentTimeMillis(), FastTouch.State.MOVE));
        touches.put(1, new TouchPoint(1, 200, 200, 128, 10, 10, System.currentTimeMillis(), FastTouch.State.MOVE));
    }

    @Benchmark
    public void benchmarkGestureMath() {
        // Measures the mathematical overhead of calculating pan, pinch, and rotation from raw touch coordinates
        fastGesture.update(touches);
    }
}

package fasttouch;

import java.awt.geom.Point2D;
import java.util.Map;
import fasttouch.FastTouch.TouchPoint;

/**
 * High-level Gesture Recognizer for FastTouch.
 * Processes raw touch maps and emits Pan, Pinch, and Rotate events.
 */
public class FastGesture {

    private float initialPinchDistance = 0f;
    private float currentPinchDistance = 0f;
    private float currentPinchScale = 1.0f;
    private float currentRotateAngle = 0.0f;

    private Point2D.Float gestureCenter = new Point2D.Float();
    private Point2D.Float lastTouchCenter = null;
    private int lastTouchCount = 0;
    private boolean isGestureActive = false;

    private final GestureListener listener;
    private java.util.function.Predicate<TouchPoint> hitTest;

    public interface GestureListener {
        void onPan(float dx, float dy, float x, float y);
        void onPinchStart(float centerX, float centerY);
        void onPinchUpdate(float scale, float angleDelta, float distance, float centerX, float centerY);
        void onPinchEnd();
    }

    public FastGesture(GestureListener listener, java.util.function.Predicate<TouchPoint> hitTest) {
        this.listener = listener;
        this.hitTest = hitTest;
    }

    /**
     * Processes the current active touches and triggers gesture events.
     * @param touches Map of active touches. Only touches relevant to the target element should be passed.
     */
    public void update(Map<Integer, TouchPoint> touches) {
        if (touches == null || touches.isEmpty()) {
            resetState();
            return;
        }

        // Calculate center of all touches
        float cx = 0, cy = 0;
        boolean allHit = true;
        for (TouchPoint tp : touches.values()) {
            cx += tp.x;
            cy += tp.y;
            if (hitTest != null && !hitTest.test(tp)) {
                allHit = false;
            }
        }
        cx /= touches.size();
        cy /= touches.size();

        // Handle Panning
        if (lastTouchCenter != null && lastTouchCount == touches.size() && (allHit || isGestureActive)) {
            float dx = cx - lastTouchCenter.x;
            float dy = cy - lastTouchCenter.y;
            if (listener != null && (dx != 0 || dy != 0)) {
                listener.onPan(dx, dy, cx, cy);
            }
        }

        // Handle Pinch / Rotate (requires exactly 2 fingers)
        if (touches.size() == 2) {
            TouchPoint[] pts = touches.values().toArray(new TouchPoint[0]);

            // Ensure consistent order to prevent 180-degree angle flips
            if (pts[0].id > pts[1].id) {
                TouchPoint tmp = pts[0];
                pts[0] = pts[1];
                pts[1] = tmp;
            }

            float dx = pts[1].x - pts[0].x;
            float dy = pts[1].y - pts[0].y;
            float distance = (float) Math.sqrt(dx * dx + dy * dy);
            float angle = (float) Math.toDegrees(Math.atan2(dy, dx));

            if (lastTouchCount != 2) {
                // Just started 2-finger gesture
                if (allHit) {
                    initialPinchDistance = distance;
                    currentPinchDistance = distance;
                    currentRotateAngle = angle;
                    gestureCenter.setLocation(cx, cy);
                    isGestureActive = true;

                    if (listener != null) {
                        listener.onPinchStart(cx, cy);
                    }
                }
            } else if (isGestureActive && initialPinchDistance > 0) {
                // Continuing gesture
                float scale = distance / initialPinchDistance;

                // Calculate rotation delta handling wrap-around
                float angleDelta = angle - currentRotateAngle;
                if (angleDelta > 180) angleDelta -= 360;
                if (angleDelta < -180) angleDelta += 360;

                currentPinchScale = scale;
                currentPinchDistance = distance;
                currentRotateAngle = angle;
                gestureCenter.setLocation(cx, cy);

                if (listener != null) {
                    listener.onPinchUpdate(scale, angleDelta, distance, cx, cy);
                }
            }
        } else if (isGestureActive) {
            // End gesture if finger count changes
            isGestureActive = false;
            currentPinchScale = 1.0f;
            currentPinchDistance = 0f;
            if (listener != null) {
                listener.onPinchEnd();
            }
        }

        lastTouchCenter = new Point2D.Float(cx, cy);
        lastTouchCount = touches.size();
    }

    public void reset() {
        resetState();
    }

    private void resetState() {
        if (isGestureActive && listener != null) {
            listener.onPinchEnd();
        }
        lastTouchCenter = null;
        lastTouchCount = 0;
        isGestureActive = false;
        currentPinchScale = 1.0f;
        currentRotateAngle = 0.0f;
        currentPinchDistance = 0f;
    }

    public boolean isGestureActive() {
        return isGestureActive;
    }

    public float getCurrentPinchDistance() {
        return currentPinchDistance;
    }

    public float getCurrentRotateAngle() {
        return currentRotateAngle;
    }

    public float getCurrentPinchScale() {
        return currentPinchScale;
    }

    public Point2D.Float getGestureCenter() {
        return gestureCenter;
    }
}

package fasttouch;

import fasttouch.FastTouch;
import fasttouch.FastTouch.TouchPoint;
import fasttheme.FastTheme;

import javax.swing.*;
import java.awt.*;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * FastTouch Demo - GC-optimierte Version mit FastGesture
 */
public class TouchDemo extends JPanel {

    public static void main(String[] args) {
        System.setProperty("sun.java2d.uiScale", "1.0");

        try {
            UIManager.setLookAndFeel(UIManager.getCrossPlatformLookAndFeelClassName());
        } catch (Exception ignored) {}

        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("FastTouch Demo - FPS: ...");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.setIconImage(createRoundIcon());

            TouchDemo demo = new TouchDemo(frame);
            frame.add(demo);
            frame.pack();
            frame.setLocationRelativeTo(null);
            frame.addNotify();

            try {
                long hwnd = FastTheme.getWindowHandle(frame);
                if (hwnd != 0) {
                    FastTheme.setTitleBarDarkMode(hwnd, true);
                    FastTheme.setTitleBarColor(hwnd, 0, 0, 0);
                    FastTheme.setTitleBarTextColor(hwnd, 255, 255, 255);
                    FastTheme.setWindowTransparency(hwnd, 224);
                }
            } catch (Throwable e) {
                System.err.println("FastTheme dark mode failed: " + e.getMessage());
            }

            frame.setVisible(true);
            demo.initFastTouch(frame);
        });
    }

    private static final int WIDTH = 1173;
    private static final int HEIGHT = 610;
    private static final int TARGET_FPS = 120;
    private static final int TOUCH_BASE_SIZE = 60;

    private static final Color[] TOUCH_ALPHA_COLORS = new Color[256];
    static {
        for (int a = 0; a < 256; a++) {
            TOUCH_ALPHA_COLORS[a] = new Color(255, 255, 255, a);
        }
    }

    private final Map<Integer, TouchPoint> activeTouches = new ConcurrentHashMap<>();
    private FastTouch touch;
    private FastGesture fastGesture;
    private final JFrame parentFrame;
    private String currentGestureText = "";

    // Box properties
    private float boxX = 400;
    private float boxY = 300;
    private final float boxWidth = 200;
    private final float boxHeight = 200;

    private float baseBoxScale = 1.0f;
    private float targetBoxScale = 1.0f;
    private float currentBoxScale = 1.0f;

    private float baseBoxRotation = 0.0f;
    private float targetBoxRotation = 0.0f;
    private float currentBoxRotation = 0.0f;

    // Reusable drawing objects
    private final Ellipse2D.Float touchCircle = new Ellipse2D.Float();
    private final Rectangle2D.Float boxRect = new Rectangle2D.Float();
    private final BasicStroke boxStroke = new BasicStroke(
            1.0f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10.0f, new float[]{2f, 2f}, 0.0f
    );
    private final AffineTransform reuseTransform = new AffineTransform();
    private final AffineTransform reuseInverse = new AffineTransform();

    public TouchDemo(JFrame parentFrame) {
        this.parentFrame = parentFrame;
        setPreferredSize(new Dimension(WIDTH, HEIGHT));
        setBackground(Color.BLACK);
        setDoubleBuffered(true);

        fastGesture = new FastGesture(new FastGesture.GestureListener() {
            @Override
            public void onPan(float dx, float dy, float x, float y) {
                // 1. Calculate the lever arm R from the center of the box to the touch point
                float rx = x - boxX;
                float ry = y - boxY;

                // 2. Cross product representing torque (R x D)
                float cross = rx * dy - ry * dx;

                // 3. Rotation delta (tune the friction factor to feel right)
                float physicsFactor = 0.001f; // Mehr Trägheit (Inertia) = weniger Rotation pro Pixel
                float angleDelta = cross * physicsFactor;

                // 4. Calculate exactly how much the rotation would move the point
                double rad = Math.toRadians(angleDelta);
                double cos = Math.cos(rad);
                double sin = Math.sin(rad);

                float rxPrime = (float) (rx * cos - ry * sin);
                float ryPrime = (float) (rx * sin + ry * cos);

                // 5. Apply the rotation and correct the translation so the box sticks to the finger!
                boxX += dx + rx - rxPrime;
                boxY += dy + ry - ryPrime;
                targetBoxRotation += angleDelta;
            }

            @Override
            public void onPinchStart(float cx, float cy) {
                baseBoxScale = targetBoxScale;
                baseBoxRotation = targetBoxRotation;
            }

            @Override
            public void onPinchUpdate(float scale, float angleDelta, float distance, float cx, float cy) {
                targetBoxScale = Math.max(0.2f, Math.min(5.0f, baseBoxScale * scale));
                targetBoxRotation += angleDelta;
            }

            @Override
            public void onPinchEnd() {
                baseBoxScale = targetBoxScale;
                baseBoxRotation = targetBoxRotation;
                currentGestureText = "";
            }
        }, tp -> isPointInBox(tp.x, tp.y));
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2d = (Graphics2D) g;
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        drawBox(g2d);

        synchronized (activeTouches) {
            drawTouches(g2d);
        }
    }

    private void startRenderLoop() {
        Thread t = new Thread(() -> {
            long lastFpsTime = System.nanoTime();
            int frames = 0;
            long frameTimeTarget = 1_000_000_000L / TARGET_FPS;
            long lastRenderTime = System.nanoTime();

            while (true) {
                long nowLoop = System.nanoTime();
                if (nowLoop - lastRenderTime < frameTimeTarget) {
                    java.util.concurrent.locks.LockSupport.parkNanos(1_000_000);
                    continue;
                }
                lastRenderTime = nowLoop;

                if (touch != null) {
                    touch.poll();
                }

                try {
                    synchronized (activeTouches) {
                        fastGesture.update(activeTouches);
                    }

                    currentBoxScale += (targetBoxScale - currentBoxScale) * 0.15f;
                    currentBoxRotation += (targetBoxRotation - currentBoxRotation) * 0.08f; // Slower lerp for more inertia feeling

                    repaint();
                    frames++;

                    long now = System.nanoTime();
                    if (now - lastFpsTime >= 1_000_000_000L) {
                        updateFPS(frames);
                        frames = 0;
                        lastFpsTime = now;
                    }
                } catch (Throwable t1) {
                    t1.printStackTrace();
                }
            }
        }, "FastTouch-RenderLoop");

        t.setDaemon(true);
        t.start();
    }

    private void drawBox(Graphics2D g2d) {
        AffineTransform old = g2d.getTransform();
        g2d.translate(boxX, boxY);
        g2d.rotate(Math.toRadians(currentBoxRotation));

        // Scale the geometry, not the Graphics2D, to keep stroke 1px thick
        float scaledW = boxWidth * currentBoxScale;
        float scaledH = boxHeight * currentBoxScale;

        boxRect.x = -scaledW / 2f;
        boxRect.y = -scaledH / 2f;
        boxRect.width = scaledW;
        boxRect.height = scaledH;

        g2d.setColor(Color.WHITE);
        g2d.setStroke(boxStroke);
        g2d.draw(boxRect);

        g2d.setTransform(old);
    }

    private void drawTouches(Graphics2D g) {
        for (TouchPoint tp : activeTouches.values()) {
            int w = Math.max(TOUCH_BASE_SIZE, tp.width);
            int h = Math.max(TOUCH_BASE_SIZE, tp.height);

            // Windows gives ~128 (512/4) when pressure is not supported.
            // If we get exactly 128 or 0, we assume no pressure hardware and use fully opaque white.
            int alpha = tp.pressure;
            if (alpha == 128 || alpha == 0) {
                alpha = 255;
            }
            alpha = Math.max(50, Math.min(255, alpha));

//            g.setColor(TOUCH_ALPHA_COLORS[alpha]);
            g.setColor(Color.WHITE);

            touchCircle.x = tp.x - w / 2f;
            touchCircle.y = tp.y - h / 2f;
            touchCircle.width = w;
            touchCircle.height = h;

            g.fill(touchCircle);
        }
    }

    private void updateFPS(int fps) {
        String suffix = currentGestureText;
        SwingUtilities.invokeLater(() ->
                parentFrame.setTitle("FastTouch Demo - FPS: " + fps + suffix)
        );
    }

    private void initFastTouch(JFrame frame) {
        touch = FastTouch.create(frame);
        touch.setGestureEnabled(true);

        touch.addListener(point -> {
            synchronized (activeTouches) {
                if (point.state == FastTouch.State.DOWN || point.state == FastTouch.State.MOVE) {
                    activeTouches.put(point.id, point);
                } else if (point.state == FastTouch.State.UP) {
                    activeTouches.remove(point.id);
                }
            }
        });

        touch.start();
        startRenderLoop();

        frame.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_ESCAPE) {
                    touch.stop();
                    System.exit(0);
                }
            }
        });
    }

    private static BufferedImage createRoundIcon() {
        BufferedImage icon = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(Color.WHITE);
        g.fill(new Ellipse2D.Float(4, 4, 56, 56));
        g.dispose();
        return icon;
    }

    private boolean isPointInBox(float x, float y) {
        reuseTransform.setToIdentity();
        reuseTransform.translate(boxX, boxY);
        reuseTransform.rotate(Math.toRadians(currentBoxRotation));
        reuseTransform.scale(currentBoxScale, currentBoxScale);

        try {
            reuseInverse.setTransform(reuseTransform);
            reuseInverse.invert();

            Point2D.Float src = new Point2D.Float(x, y);
            Point2D.Float dst = new Point2D.Float();
            reuseInverse.transform(src, dst);

            return dst.x >= -boxWidth / 2f && dst.x <= boxWidth / 2f &&
                    dst.y >= -boxHeight / 2f && dst.y <= boxHeight / 2f;

        } catch (NoninvertibleTransformException e) {
            return false;
        }
    }
}

package fasttouch;

import fastcore.FastCore;
import java.util.ArrayList;
import java.util.List;

/**
 * FastTouch - Native Windows Touchscreen Input API for Java.
 * 
 * <p>Provides low-latency, native-quality touchscreen input for Java applications
 * using the Windows WM_POINTER API (Windows 8+). Supports multi-touch tracking,
 * pressure sensitivity, and contact size measurement.</p>
 * 
 * <p><b>Key Features:</b></p>
 * <ul>
 *   <li><b>Multi-Touch:</b> Track up to 10 simultaneous touch points</li>
 *   <li><b>Pressure Sensing:</b> 0-255 pressure levels from capacitive touch</li>
 *   <li><b>Contact Size:</b> Width and height of finger contact area</li>
 *   <li><b>Low Latency:</b> Native event-driven architecture, no polling required</li>
 *   <li><b>Thread-Safe:</b> All callbacks on EDT, synchronized touch state</li>
 * </ul>
 * 
 * <p><b>Basic Usage:</b></p>
 * <pre>
 * JFrame frame = new JFrame("Touch Demo");
 * frame.setVisible(true);
 * 
 * // Initialize touch input for the window
 * FastTouch touch = FastTouch.create(frame);
 * 
 * // Add touch listener
 * touch.addListener(point -&gt; {
 *     System.out.println("Touch " + point.id + " at (" + point.x + "," + point.y + ")");
 *     if (point.state == FastTouch.State.DOWN) {
 *         System.out.println("  Pressure: " + point.pressure);
 *         System.out.println("  Size: " + point.width + "x" + point.height);
 *     }
 * });
 * 
 * // Start touch processing
 * touch.start();
 * </pre>
 * 
 * <p><b>Thread Safety:</b> All touch events are delivered on the Swing Event Dispatch Thread (EDT).
 * The touch processing runs in a background daemon thread that polls at ~120Hz.</p>
 * 
 * <p><b>Platform Support:</b> Windows 8/10/11 only (requires WM_POINTER API).</p>
 * 
 * @author FastJava Team
 * @version 0.1.0
 * @since 0.1.0
 * @see <a href="https://github.com/andrestubbe/FastTouch">GitHub Repository</a>
 */
public class FastTouch {
    
    static {
        FastCore.loadLibrary("fasttouch");
    }
    
    /**
     * Immutable data class representing a single touch point.
     * 
     * <p>Contains all information about a touch event including position,
     * pressure, contact size, and timing. TouchPoint instances are immutable
     * and thread-safe.</p>
     * 
     * <p><b>Field Summary:</b></p>
     * <table border="1">
     *   <tr><th>Field</th><th>Range/Unit</th><th>Description</th></tr>
     *   <tr><td>{@link #id}</td><td>0-9</td><td>Unique touch ID for multi-touch tracking</td></tr>
     *   <tr><td>{@link #x}, {@link #y}</td><td>pixels</td><td>Window-relative coordinates</td></tr>
     *   <tr><td>{@link #pressure}</td><td>0-255</td><td>Contact pressure (0=light, 255=heavy)</td></tr>
     *   <tr><td>{@link #width}, {@link #height}</td><td>pixels</td><td>Approximate contact area</td></tr>
     *   <tr><td>{@link #state}</td><td>enum</td><td>DOWN, MOVE, or UP</td></tr>
     *   <tr><td>{@link #timestamp}</td><td>ms</td><td>Event time (System.currentTimeMillis)</td></tr>
     * </table>
     */
    public static final class TouchPoint {
        
        /** Unique touch identifier (0-9) for tracking individual fingers. */
        public final int id;
        
        /** X coordinate in window-relative pixels (0 = left edge). */
        public final int x;
        
        /** Y coordinate in window-relative pixels (0 = top edge). */
        public final int y;
        
        /** Contact pressure level, normalized to 0-255 range.
         *  0 = very light touch, 255 = maximum pressure. */
        public final int pressure;
        
        /** Approximate contact width in pixels (ellipse major axis). */
        public final int width;
        
        /** Approximate contact height in pixels (ellipse minor axis). */
        public final int height;
        
        /** Event timestamp in milliseconds (from GetTickCount). */
        public final long timestamp;
        
        /** Touch event state: DOWN (finger first contacts), MOVE (dragging), UP (lifted). */
        public final State state;
        
        // Stylus/Pen support (reserved for future use)
        /** Touch orientation in degrees (0 = upright). Currently 0. */
        public final float orientation;
        
        /** X-axis tilt angle in degrees (-90 to +90). Currently 0. */
        public final float tiltX;
        
        /** Y-axis tilt angle in degrees (-90 to +90). Currently 0. */
        public final float tiltY;
        
        /** Confidence level 0-255 (255 = high confidence). Currently 255. */
        public final int confidence;
        
        public TouchPoint(int id, int x, int y, int pressure, int width, int height, 
                         long timestamp, State state) {
            this(id, x, y, pressure, width, height, timestamp, state, 
                 0f, 0f, 0f, 255);
        }
        
        public TouchPoint(int id, int x, int y, int pressure, int width, int height, 
                         long timestamp, State state,
                         float orientation, float tiltX, float tiltY, int confidence) {
            this.id = id;
            this.x = x;
            this.y = y;
            this.pressure = pressure;
            this.width = width;
            this.height = height;
            this.timestamp = timestamp;
            this.state = state;
            this.orientation = orientation;
            this.tiltX = tiltX;
            this.tiltY = tiltY;
            this.confidence = confidence;
        }
        
        @Override
        public String toString() {
            return String.format("TouchPoint[id=%d, pos=(%d,%d), pressure=%d, size=%dx%d, %s]", 
                id, x, y, pressure, width, height, state);
        }
    }
    
    /**
     * Touch event lifecycle states.
     * 
     * <p>Each touch point progresses through: {@link #DOWN} -&gt; {@link #MOVE}* -&gt; {@link #UP}</p>
     */
    public enum State {
        /** Finger first contacts the screen. Always the first event for a touch ID. */
        DOWN,
        /** Finger is dragging across the screen. May be delivered multiple times. */
        MOVE,
        /** Finger lifted from screen. Always the last event for a touch ID. */
        UP
    }
    
    /**
     * Listener interface for receiving touch events.
     * 
     * <p>Implement this interface to receive touch notifications. Register your
     * listener using {@link #addListener(TouchListener)}.</p>
     * 
     * <p><b>Thread Safety:</b> Callbacks are delivered from the touch polling thread,
     * NOT the EDT. Use {@link SwingUtilities#invokeLater} for UI updates.</p>
     * 
     * @see #addListener(TouchListener)
     * @see #removeListener(TouchListener)
     */
    public interface TouchListener {
        
        /**
         * Called when a touch event occurs.
         * 
         * @param point the touch point data (immutable, never null)
         */
        void onTouch(TouchPoint point);
    }
    
    // Native Methoden
    private static native void initNative(long hwnd);
    private static native void pollNative();  // DEPRECATED - use event-driven
    private static native void stopNative();
    private static native void clearUpSlotById(int id);
    private static native int getTouchCount();
    private static native int getTouchId(int index);
    
    // NEW: Native callback entry point (called from C++ when touch event occurs)
    private static void onNativeTouch(int id, int x, int y, int pressure, 
                                       int width, int height, int state, long timestamp) {
        TouchPoint point = new TouchPoint(id, x, y, pressure, width, height, 
                                         timestamp, State.values()[state]);
        // Notify all listeners directly on event
        for (TouchListener listener : listeners) {
            listener.onTouch(point);
        }
    }
    private static native int getTouchX(int index);
    private static native int getTouchY(int index);
    private static native int getTouchPressure(int index);
    private static native int getTouchWidth(int index);
    private static native int getTouchHeight(int index);
    private static native int getTouchState(int index);
    private static native long getTouchTimestamp(int index);
    
    private long hwnd;
    private static final java.util.concurrent.CopyOnWriteArrayList<TouchListener> listeners = new java.util.concurrent.CopyOnWriteArrayList<>();  // static for native callback
    private volatile boolean running = false;
    private Thread pollThread = null;
    private final java.util.Set<Integer> firedUpEvents = new java.util.HashSet<>();  // Track already fired UP events
    private final java.util.Map<Integer, TouchPoint> lastFiredState = new java.util.HashMap<>(); // Filter MOVE spam
    
    /**
     * Creates a FastTouch instance for the given JFrame.
     * 
     * <p>This method initializes the native touch input subsystem for the specified
     * Swing window. The frame must be visible with a title set before calling this
     * method (use after {@code setVisible(true)}).</p>
     * 
     * <p>The method searches for the native window handle using the frame title.
     * It retries automatically for up to 3 seconds to allow the native window
     * to be created by the OS.</p>
     * 
     * @param frame the JFrame to receive touch input (must be visible with title)
     * @return initialized FastTouch instance
     * @throws RuntimeException if the native window cannot be found
     * 
     * @see #start()
     */
    public static FastTouch create(javax.swing.JFrame frame) {
        System.out.println("[FastTouch] create() called");
        
        // Warte bis Fenster sichtbar und Titel gesetzt ist
        System.out.println("[FastTouch] Waiting for frame...");
        int waitRetries = 0;
        while ((!frame.isVisible() || frame.getTitle() == null || frame.getTitle().isEmpty()) && waitRetries < 50) {
            try { Thread.sleep(10); } catch (InterruptedException e) {}
            waitRetries++;
        }
        
        String title = frame.getTitle();
        System.out.println("[FastTouch] Frame title: '" + title + "' (length=" + (title != null ? title.length() : 0) + ")");
        
        // Versuche verschiedene Titel-Varianten
        long hwnd = 0;
        String[] titleVariants = {
            title,
            title != null ? title.trim() : null,
            "FastTouch Demo",
            "FastTouch"
        };
        
        int retries = 0;
        while (hwnd == 0 && retries < 30) {
            for (String variant : titleVariants) {
                if (variant != null && !variant.isEmpty()) {
                    hwnd = findWindow(variant);
                    if (hwnd != 0) {
                        System.out.println("[FastTouch] Found with title: '" + variant + "'");
                        break;
                    }
                }
            }
            if (hwnd == 0) {
                System.out.println("[FastTouch] Retry " + (retries + 1) + "/30...");
                try { Thread.sleep(100); } catch (InterruptedException e) {}
                retries++;
            }
        }
        
        if (hwnd == 0) {
            throw new RuntimeException("[FastTouch] Fenster nicht gefunden. Titel war: '" + title + "'");
        }
        System.out.println("[FastTouch] Window handle found: " + hwnd);
        
        return new FastTouch(hwnd);
    }
    
    /**
     * Creates a FastTouch instance by natively searching for a Window Title.
     * 
     * <p>This method bypasses JFrame entirely and allows attaching the touch
     * engine to any native Windows HWND, including the Windows Console or Windows Terminal.</p>
     * 
     * @param windowTitle the exact title of the window to hook into
     * @return initialized FastTouch instance
     * @throws RuntimeException if the native window cannot be found
     */
    public static FastTouch create(String windowTitle) {
        System.out.println("[FastTouch] create(String) called for title: '" + windowTitle + "'");
        long hwnd = 0;
        int retries = 0;
        
        while (hwnd == 0 && retries < 30) {
            hwnd = findWindow(windowTitle);
            if (hwnd == 0) {
                try { Thread.sleep(100); } catch (InterruptedException e) {}
                retries++;
            }
        }
        
        if (hwnd == 0) {
            throw new RuntimeException("[FastTouch] Window not found. Title was: '" + windowTitle + "'");
        }
        System.out.println("[FastTouch] Window handle found: " + hwnd);
        
        return new FastTouch(hwnd);
    }
    
    private static native long findWindow(String title);
    
    private FastTouch(long hwnd) {
        System.out.println("[FastTouch] Constructor called with hwnd=" + hwnd);
        this.hwnd = hwnd;
        System.out.println("[FastTouch] Calling initNative...");
        initNative(hwnd);
        System.out.println("[FastTouch] initNative completed");
    }
    
    /**
     * Registers a touch listener to receive touch events.
     * 
     * <p>Multiple listeners can be registered. All listeners receive all touch events
     * in the order they were added. Listeners are stored statically (shared across
     * all FastTouch instances).</p>
     * 
     * @param listener the listener to add (must not be null)
     * @throws NullPointerException if listener is null
     * @see TouchListener
     * @see #removeListener(TouchListener)
     */
    public void addListener(TouchListener listener) {
        listeners.add(listener);
    }
    
    /**
     * Unregisters a previously added touch listener.
     * 
     * @param listener the listener to remove
     * @see #addListener(TouchListener)
     */
    public void removeListener(TouchListener listener) {
        listeners.remove(listener);
    }
    
    /**
     * Starts the touch polling thread.
     * 
     * <p>Creates a daemon thread that polls for touch events at approximately
     * 120Hz (8ms intervals). Touch events are delivered to all registered
     * listeners via the touch polling thread.</p>
     * 
     * <p>This method is idempotent - calling it multiple times has no effect
     * if already running. The thread automatically stops when {@link #stop()} is
     * called or when the JVM exits (daemon thread).</p>
     * 
     * @see #stop()
     */
    public void start() {
        if (running) return;
        running = true;
        // Polling is now driven manually by the application render loop
    }
    
    /**
     * Stops the touch polling thread.
     * 
     * <p>Sets the running flag to false, causing the polling thread to exit
     * on its next iteration. This method returns immediately - the thread may
     * continue for a few more milliseconds.</p>
     * 
     * @see #start()
     */
    public void stop() {
        running = false;
        if (pollThread != null) {
            try {
                pollThread.join(500); // Wait for polling to cleanly finish
            } catch (InterruptedException e) {}
            pollThread = null;
        }
        stopNative();
    }
    
    /**
     * Polls for touch events once (blocking).
     * 
     * <p>Processes pending Windows messages and checks for touch events.
     * Normally called automatically by the polling thread - manual calls
     * are not required in typical usage.</p>
     * 
     * <p>This method is thread-safe and can be called from any thread.</p>
     * 
     * @see #start()
     */
    public void poll() {
        pollNative();
        
        int count = getTouchCount();
        
        if (count == 0) {
            // Clean up old state when no fingers are touching to prevent memory leaks
            firedUpEvents.clear();
            lastFiredState.clear();
        }
        
        for (int i = 0; i < count; i++) {
            int id = getTouchId(i);
            int x = getTouchX(i);
            int y = getTouchY(i);
            int pressure = getTouchPressure(i);
            int width = getTouchWidth(i);
            int height = getTouchHeight(i);
            int stateCode = getTouchState(i);
            long timestamp = getTouchTimestamp(i);
            
            State state = stateCode == 0 ? State.DOWN : 
                         stateCode == 1 ? State.MOVE : State.UP;
            
            // UP-Events nur einmal feuern!
            if (state == State.UP) {
                if (firedUpEvents.contains(id)) {
                    continue;  // Bereits gefeuert, überspringen
                }
                firedUpEvents.add(id);  // Markieren als gefeuert
                lastFiredState.remove(id);
                clearUpSlotById(id); // Notify C++ to release this specific slot
            } else if (state == State.DOWN) {
                // Debug: DOWN event received
                firedUpEvents.remove(id);  // UP-Tracking zurücksetzen
            } else {
                // Bei MOVE: UP-Tracking für diese ID zurücksetzen (falls nötig)
                firedUpEvents.remove(id);
            }
            
            TouchPoint point = new TouchPoint(id, x, y, pressure, width, height, timestamp, state);
            
            // Filter identical MOVE events
            if (state == State.MOVE) {
                TouchPoint last = lastFiredState.get(id);
                if (last != null && last.x == x && last.y == y && last.pressure == pressure) {
                    continue; // Skip firing if nothing changed
                }
            }
            if (state != State.UP) {
                lastFiredState.put(id, point);
            }
            
            // Benachrichtige alle Listener
            for (TouchListener listener : listeners) {
                try {
                    listener.onTouch(point);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }
    
    /**
     * Checks if a touch input device is available.
     * 
     * <p>Returns true if the system has a touchscreen or precision touchpad
     * that can be used for input. Also returns false on Windows 7 or earlier
     * (requires Windows 8+ WM_POINTER API).</p>
     * 
     * @return true if touch input is available, false otherwise
     * @see #getMaxTouchPoints()
     */
    public static native boolean isTouchAvailable();
    
    /**
     * Returns the maximum number of simultaneous touch points supported.
     * 
     * <p>Windows theoretically supports up to 256 touch points, but most
     * hardware supports 5-10 simultaneous touches. This method returns 10
     * as a practical limit for typical consumer hardware.</p>
     * 
     * @return maximum number of simultaneous touch points (currently 10)
     * @see #isTouchAvailable()
     */
    public static native int getMaxTouchPoints();
    
    // ============================================================================
    // GESTURE SUPPORT (Native Pinch/Rotate via WM_GESTURE)
    // ============================================================================
    
    private static final java.util.concurrent.CopyOnWriteArrayList<GestureCallback> gestureCallbacks = new java.util.concurrent.CopyOnWriteArrayList<>();
    
    /**
     * Callback interface for native gesture events (Pinch/Rotate).
     * Used by FastGesture to receive native gesture events from Windows WM_GESTURE.
     * 
     * @since 1.3.0
     */
    public interface GestureCallback {
        /** Called when a pinch gesture is detected. */
        void onPinch(float scale, float centerX, float centerY);
        /** Called when a rotate gesture is detected. */
        void onRotate(float angle, float centerX, float centerY);
        /** Called when the current gesture ends. */
        void onGestureEnd();
    }
    
    /**
     * Registers a gesture callback for native Pinch/Rotate events.
     * Used internally by FastGesture.
     * 
     * @param callback the callback to register
     */
    public static void addGestureCallback(GestureCallback callback) {
        if (callback != null) {
            gestureCallbacks.add(callback);
        }
    }
    
    /**
     * Unregisters a gesture callback.
     * 
     * @param callback the callback to remove
     */
    public static void removeGestureCallback(GestureCallback callback) {
        gestureCallbacks.remove(callback);
    }
    
    /**
     * Called from native code when a pinch gesture is detected.
     * 
     * @param scale zoom factor (1.0 = neutral)
     * @param centerX pinch center X coordinate
     * @param centerY pinch center Y coordinate
     */
    @SuppressWarnings("unused")
    private static void onNativePinch(float scale, float centerX, float centerY) {
        for (GestureCallback cb : gestureCallbacks) {
            try {
                cb.onPinch(scale, centerX, centerY);
            } catch (Exception e) {
                System.err.println("[FastTouch] Gesture callback error: " + e.getMessage());
            }
        }
    }
    
    /**
     * Called from native code when a rotate gesture is detected.
     * 
     * @param angle rotation in degrees (positive = clockwise)
     * @param centerX rotation center X coordinate
     * @param centerY rotation center Y coordinate
     */
    @SuppressWarnings("unused")
    private static void onNativeRotate(float angle, float centerX, float centerY) {
        for (GestureCallback cb : gestureCallbacks) {
            try {
                cb.onRotate(angle, centerX, centerY);
            } catch (Exception e) {
                System.err.println("[FastTouch] Gesture callback error: " + e.getMessage());
            }
        }
    }
    
    /**
     * Called from native code when a gesture ends.
     */
    @SuppressWarnings("unused")
    private static void onNativeGestureEnd() {
        for (GestureCallback cb : gestureCallbacks) {
            try {
                cb.onGestureEnd();
            } catch (Exception e) {
                System.err.println("[FastTouch] Gesture callback error: " + e.getMessage());
            }
        }
    }
    
    /**
     * Enables or disables native gesture recognition (WM_GESTURE).
     * Must be called after create() to receive Pinch/Rotate events.
     * 
     * @param enable true to enable gesture recognition
     */
    public native void setGestureEnabled(boolean enable);
}

/**
 * @file FastTouch.cpp
 * @brief Native Windows Touchscreen Input Implementation for Java
 * 
 * @details Implements the JNI native layer for FastTouch using the Windows
 * WM_POINTER API (Windows 8+). Provides low-latency touch event capture
 * with multi-touch support, pressure sensitivity, and contact size measurement.
 * 
 * @par Architecture
 * - Window subclassing to intercept WM_POINTER* messages
 * - Thread-safe touch state storage with CriticalSection
 * - Automatic stale touch detection (500ms timeout)
 * 
 * @par Platform Requirements
 * - Windows 8 or later (WM_POINTER API)
 * - user32.dll (for GetPointerTouchInfo)
 * 
 * @author FastJava Team
 * @version 1.1.0
 * @since 1.0.0
 */

#include <jni.h>
#include <windows.h>
#include <stdio.h>

#pragma comment(lib, "user32.lib")

// ============================================================================
// WM_POINTER API CONSTANTS (Windows 8+)
// ============================================================================

#ifndef WM_POINTERDOWN
/** @brief WM_POINTERDOWN message constant (0x0246) - Finger contacts screen */
#define WM_POINTERDOWN 0x0246
/** @brief WM_POINTERUP message constant (0x0247) - Finger lifts from screen */
#define WM_POINTERUP 0x0247
/** @brief WM_POINTERUPDATE message constant (0x0245) - Finger moves on screen */
#define WM_POINTERUPDATE 0x0245
/** @brief Extract pointer ID from WPARAM */
#define GET_POINTERID_WPARAM(wParam) (LOWORD(wParam))
#endif

// ============================================================================
// WM_GESTURE API CONSTANTS (Windows 7+)
// ============================================================================

#ifndef WM_GESTURE
/** @brief WM_GESTURE message constant (0x0119) - Gesture detected */
#define WM_GESTURE 0x0119
/** @brief Begin gesture message */
#define WM_GESTURENOTIFY 0x011A
#endif

#ifndef GID_BEGIN
/** @brief Gesture IDs for WM_GESTURE */
#define GID_BEGIN       1
#define GID_END         2
#define GID_ZOOM        3   /**< Pinch/Zoom gesture */
#define GID_PAN         4
#define GID_ROTATE      5   /**< Rotation gesture */
#define GID_TWOFINGERTAP 6
#define GID_ROLLOVER    7
#endif

/** @brief Enable/disable gesture flags */
#ifndef GF_BEGIN
#define GF_BEGIN 0x00000001
#define GF_INERTIA 0x00000002
#define GF_END 0x00000004
#endif

/** @brief Decode zoom distance from gesture argument */
#ifndef GID_ZOOM_DISTANCE_FROM_ARGUMENT
#define GID_ZOOM_DISTANCE_FROM_ARGUMENT(arg) (float)((arg) & 0xFFFF)
#endif
/** @brief Decode rotation angle from gesture argument (in radians) */
#ifndef GID_ROTATE_ANGLE_FROM_ARGUMENT
#define GID_ROTATE_ANGLE_FROM_ARGUMENT(arg) (float)((arg) / 65536.0)
#endif

/**
 * @brief Windows GESTUREINFO structure for gesture data (local definition)
 */
typedef struct {
    UINT cbSize;           /**< Size of structure */
    DWORD dwFlags;         /**< Gesture flags (GF_BEGIN, GF_INERTIA, GF_END) */
    DWORD dwID;            /**< Gesture ID (GID_ZOOM, GID_ROTATE, etc.) */
    HWND hwndTarget;       /**< Target window */
    POINTS ptsLocation;    /**< Gesture location (x, y in screen coords) */
    DWORD dwInstanceID;    /**< Instance ID */
    DWORD dwSequenceID;    /**< Sequence ID */
    ULONGLONG ullArguments;/**< Gesture-specific arguments */
    UINT cbExtraArgs;      /**< Size of extra arguments */
} FASTTOUCH_GESTUREINFO;

// ============================================================================
// POINTER API FUNCTION TYPEDEFS (Dynamically Loaded)
// ============================================================================

typedef BOOL (WINAPI *GetPointerTypeFunc)(UINT32 pointerId, POINTER_INPUT_TYPE *pointerType);
typedef BOOL (WINAPI *GetPointerTouchInfoFunc)(UINT32 pointerId, POINTER_TOUCH_INFO *touchInfo);
typedef BOOL (WINAPI *GetPointerFrameTouchInfoFunc)(UINT32 pointerId, UINT32 *pointerCount, POINTER_TOUCH_INFO *touchInfo);
typedef BOOL (WINAPI *GetGestureInfoFunc)(HGESTUREINFO hGestureInfo, FASTTOUCH_GESTUREINFO* pGestureInfo);
typedef BOOL (WINAPI *SetGestureConfigFunc)(HWND hwnd, DWORD dwReserved, UINT cIDs, PGESTURECONFIG pGestureConfig, UINT cbSize);

static GetPointerTouchInfoFunc pGetPointerTouchInfo = nullptr;  /**< Dynamically loaded GetPointerTouchInfo */

// ============================================================================
// GLOBAL STATE
// ============================================================================

static HWND g_hwnd = nullptr;           /**< Target window handle for touch input */
static bool g_initialized = false;      /**< True if subsystem initialized */
static bool g_touchAvailable = false;   /**< True if WM_POINTER API is available */
static bool g_gestureAvailable = false;
static bool g_gestureEnabled = false;   /**< True if gesture recognition enabled */

// Gesture function pointer
static GetGestureInfoFunc pGetGestureInfo = nullptr;
static SetGestureConfigFunc pSetGestureConfig = nullptr;

// JNI callback state (reserved for future event-driven mode)
static JavaVM* g_javaVM = nullptr;      /**< Cached JavaVM for callbacks */
static jclass g_fastTouchClass = nullptr; /**< Cached FastTouch class reference */
static jmethodID g_onPinchMethod = nullptr;
static jmethodID g_onRotateMethod = nullptr;
static jmethodID g_onGestureEndMethod = nullptr;
static jmethodID g_onNativeTouchMethod = nullptr; /**< Cached onNativeTouch method ID */

/** @brief Maximum number of touch points supported simultaneously */
#define MAX_TOUCH_POINTS 20

/**
 * @brief Internal touch point storage structure
 * 
 * Stores all information about a single touch point including position,
 * pressure, contact size, and lifecycle state.
 */
struct TouchPoint {
    int id;           /**< Unique touch identifier (0-9) */
    int x;            /**< X coordinate in client pixels */
    int y;            /**< Y coordinate in client pixels */
    int pressure;     /**< Pressure 0-255 (scaled from Windows 0-1024) */
    int width;        /**< Contact width in pixels */
    int height;       /**< Contact height in pixels */
    long timestamp;   /**< Event timestamp (GetTickCount) */
    int state;       // -1=NONE, 0=DOWN, 1=MOVE, 2=UP
    bool active;
};

static TouchPoint g_touchPoints[MAX_TOUCH_POINTS];
static int g_activeSlots[MAX_TOUCH_POINTS]; // Snapshot of active slot indices
static int g_snapshotCount = 0;             // Number of active slots in snapshot
static int g_touchCount = 0;                        /**< Current number of active+ending touches */
static CRITICAL_SECTION g_touchLock;                /**< Thread lock for touch state access */

static WNDPROC g_origWndProc = nullptr;  /**< Original window procedure (for subclass chaining) */

/**
 * @brief Window procedure hook for intercepting WM_POINTER messages
 * 
 * @details Subclasses the target window to capture touch events. Processes
 * WM_POINTERDOWN, WM_POINTERUPDATE, and WM_POINTERUP messages, extracting
 * touch coordinates, pressure, and contact size. Chains to original WNDPROC
 * for non-touch messages.
 * 
 * @param hwnd Window handle receiving the message
 * @param msg Windows message identifier
 * @param wParam Message-specific parameter (contains pointer ID)
 * @param lParam Message-specific parameter (contains coordinates)
 * @return LRESULT Message result (0 if processed, chained otherwise)
 * 
 * @note Thread-safe: Uses g_touchLock CriticalSection
 * @see Java_fasttouch_FastTouch_initNative
 */
static LRESULT CALLBACK TouchWndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    switch (msg) {
        case WM_POINTERDOWN:
        case WM_POINTERUPDATE:
        case WM_POINTERUP:
        case 0x024C: { // WM_POINTERCAPTURECHANGED
            UINT32 pointerId = GET_POINTERID_WPARAM(wParam);
            
            EnterCriticalSection(&g_touchLock);
            
            // Find existing touch slot
            int slot = -1;
            for (int j = 0; j < MAX_TOUCH_POINTS; j++) {
                if (g_touchPoints[j].id == (int)pointerId && g_touchPoints[j].active) {
                    slot = j;
                    break;
                }
            }
            
            // If it's a new touch point, allocate a slot before querying info
            if (msg == WM_POINTERDOWN && slot == -1) {
                for (int j = 0; j < MAX_TOUCH_POINTS; j++) {
                    if (!g_touchPoints[j].active && g_touchPoints[j].state != 2) {
                        slot = j;
                        g_touchPoints[j].active = true;
                        g_touchPoints[j].id = pointerId;
                        g_touchPoints[j].timestamp = GetTickCount();
                        
                        break;
                    }
                }
            }
            
            // Handle UP separately - pointer info may not be available
            if (msg == WM_POINTERUP || msg == 0x024C) {
                if (slot != -1) {
                    g_touchPoints[slot].state = 2; // UP
                    g_touchPoints[slot].active = false;
                    
                }
                LeaveCriticalSection(&g_touchLock);
                break;
            }
            
            // For DOWN/UPDATE, get touch info
            if (pGetPointerTouchInfo && slot != -1) {
                POINTER_TOUCH_INFO touchInfo;
                if (pGetPointerTouchInfo(pointerId, &touchInfo)) {
                    // Coordinates - handle UI scaling (Windows gives physical pixels)
                    POINT pt;
                    pt.x = touchInfo.pointerInfo.ptPixelLocation.x;
                    pt.y = touchInfo.pointerInfo.ptPixelLocation.y;
                    ScreenToClient(hwnd, &pt);
                    
                    g_touchPoints[slot].x = pt.x;
                    g_touchPoints[slot].y = pt.y;
                    g_touchPoints[slot].timestamp = GetTickCount();
                    
                    // Contact size
                    g_touchPoints[slot].width = touchInfo.rcContact.right - touchInfo.rcContact.left;
                    g_touchPoints[slot].height = touchInfo.rcContact.bottom - touchInfo.rcContact.top;
                    
                    // Pressure (0-1024 from Windows API, we scale to 0-255)
                    g_touchPoints[slot].pressure = (touchInfo.pressure * 255) / 1024;
                    
                    // State
                    if (msg == WM_POINTERDOWN) {
                        g_touchPoints[slot].state = 0; // DOWN
                        
                    } else {
                        g_touchPoints[slot].state = 1; // MOVE
                        
                        // Only log if position changed to avoid spam from pressure/keep-alive updates
                        static int lastX[MAX_TOUCH_POINTS] = {0};
                        static int lastY[MAX_TOUCH_POINTS] = {0};
                        
                        if (pt.x != lastX[slot] || pt.y != lastY[slot]) {
                            static int moveCount = 0;
                            if (++moveCount % 10 == 0) {
                                
                            }
                            lastX[slot] = pt.x;
                            lastY[slot] = pt.y;
                        }
                    }
                }
            }
            
            // Count active touches
            g_touchCount = 0;
            for (int i = 0; i < MAX_TOUCH_POINTS; i++) {
                if (g_touchPoints[i].active || g_touchPoints[i].state == 2) {
                    g_touchCount++;
                }
            }
            
            LeaveCriticalSection(&g_touchLock);
            break;
        }
        
        case WM_GESTURE: {
            if (!g_gestureEnabled || !pGetGestureInfo) {
                break;
            }
            if (pGetGestureInfo) {
                FASTTOUCH_GESTUREINFO gi;
                ZeroMemory(&gi, sizeof(gi));
                gi.cbSize = sizeof(FASTTOUCH_GESTUREINFO);
                
                if (pGetGestureInfo((HGESTUREINFO)lParam, &gi)) {
                    // Check if gesture is ending
                    if (gi.dwFlags & 0x00000004) { // GF_END
                        if (g_javaVM && g_fastTouchClass && g_onGestureEndMethod) {
                            JNIEnv* env = nullptr;
                            bool attached = false;
                            if (g_javaVM->GetEnv((void**)&env, JNI_VERSION_1_6) != JNI_OK) {
                                g_javaVM->AttachCurrentThread((void**)&env, nullptr);
                                attached = true;
                            }
                            if (env) {
                                env->CallStaticVoidMethod(g_fastTouchClass, g_onGestureEndMethod);
                                if (attached) {
                                    g_javaVM->DetachCurrentThread();
                                }
                            }
                        }
                    }
                    
                    // Extract coordinates
                    POINT pt;
                    pt.x = gi.ptsLocation.x;
                    pt.y = gi.ptsLocation.y;
                    ScreenToClient(hwnd, &pt);
                    
                    switch (gi.dwID) {
                    case GID_ZOOM: {
                        // Pinch/Zoom gesture - extract distance and normalize to scale
                        float distance = GID_ZOOM_DISTANCE_FROM_ARGUMENT(gi.ullArguments);
                        // Normalize scale: distance around 100 = neutral (1.0)
                        float scale = distance / 100.0f;
                        if (scale < 0.1f) scale = 0.1f; // Clamp minimum
                        
                        
                        
                        // Call Java callback via JNI
                        if (g_javaVM && g_fastTouchClass && g_onPinchMethod) {
                            JNIEnv* env = nullptr;
                            bool attached = false;
                            if (g_javaVM->GetEnv((void**)&env, JNI_VERSION_1_6) != JNI_OK) {
                                g_javaVM->AttachCurrentThread((void**)&env, nullptr);
                                attached = true;
                            }
                            if (env) {
                                env->CallStaticVoidMethod(g_fastTouchClass, g_onPinchMethod, 
                                    scale, (float)pt.x, (float)pt.y);
                                if (attached) {
                                    g_javaVM->DetachCurrentThread();
                                }
                            }
                        }
                        CloseGestureInfoHandle((HGESTUREINFO)lParam);
                        return 0;
                    }
                    
                    case GID_ROTATE: {
                        // Rotation gesture - extract angle and convert to degrees
                        float angleRad = GID_ROTATE_ANGLE_FROM_ARGUMENT(gi.ullArguments);
                        float angleDeg = angleRad * (180.0f / 3.14159265f);
                        
                        
                        
                        // Call Java callback via JNI
                        if (g_javaVM && g_fastTouchClass && g_onRotateMethod) {
                            JNIEnv* env = nullptr;
                            bool attached = false;
                            if (g_javaVM->GetEnv((void**)&env, JNI_VERSION_1_6) != JNI_OK) {
                                g_javaVM->AttachCurrentThread((void**)&env, nullptr);
                                attached = true;
                            }
                            if (env) {
                                env->CallStaticVoidMethod(g_fastTouchClass, g_onRotateMethod, 
                                    angleDeg, (float)pt.x, (float)pt.y);
                                if (attached) {
                                    g_javaVM->DetachCurrentThread();
                                }
                            }
                        }
                        CloseGestureInfoHandle((HGESTUREINFO)lParam);
                        return 0;
                    }
                    }
                    // For unhandled gestures, we must close the handle
                    CloseGestureInfoHandle((HGESTUREINFO)lParam);
                }
            }
            break;
        }
    }
    
    if (g_origWndProc) {
        return CallWindowProc(g_origWndProc, hwnd, msg, wParam, lParam);
    }
    return DefWindowProc(hwnd, msg, wParam, lParam);
}

